nav.addEventListener('click',event=>{const asset=event.target.closest('[data-asset]')?.dataset.asset;if(['crypto','stocks','indices','india'].includes(asset)&&window.history?.replaceState)try{window.history.replaceState(null,'','#'+asset)}catch{}});
if(typeof location!=='undefined'){const initial=location.hash.slice(1);if(['crypto','stocks','indices','india'].includes(initial))nav.querySelector('[data-asset='+initial+']')?.click();}
setInterval(()=>{if(!india.hidden&&latestQuote&&$('indiaQuoteText')){const q=latestQuote,age=q.at?Math.max(0,Math.floor((Date.now()-q.at)/1000)):null,fresh=q.valid&&age!==null&&age<=15;$('indiaQuoteText').textContent=q.symbol+': ₹'+num(q.price)+' · source '+when(q.at)+' · '+(age===null?'Age unknown':age+' seconds old')+' · '+(fresh?'Fresh':'Stale / market closed')+' · fetched '+when(q.fetched)}},1000);
setInterval(()=>{if(!india.hidden&&!document.hidden&&$('indiaAuto')?.checked&&['trade','setups'].includes(panel))india.refreshQuote?.()},5000);
